            vCos[j] = cos(b->owner->vRotation[j]/180*Q_PI);
          }
        }


	      qglBegin (GL_TRIANGLES);

        vec5_t vTest[3];
        for (i = 0; i < model->nTriCount; i++)
        {
          for (j = 0; j < 3; j++)
          {
#if 1
            float x = model->pTriList[i].v[j][0] + v[0];
            float y = model->pTriList[i].v[j][1] + v[1];
            if (a)
            {
              float x2 = (((x - v[0]) * c) - ((y - v[1]) * s)) + v[0];
