      vCenter[0] += 16;
      qglVertex3fv(vCenter);
      vCenter[0] -= 8;
      vCenter[1] -= 8;
      qglVertex3fv(vCenter);
      vCenter[1] += 16;
      qglVertex3fv(vCenter);
      vCenter[1] -= 8;
      vCenter[2] -= 8;
      qglVertex3fv(vCenter);
      vCenter[2] += 16;
      qglVertex3fv(vCenter);
      vCenter[2] -= 8;
      qglEnd();

      VectorCopy(vCenter, vMin);
