      vMin[0] -= 4;
      vMin[1] -= 4;
      vMin[2] -= 4;
      vMax[0] += 4;
      vMax[1] += 4;
      vMax[2] += 4;

		    qglBegin(GL_LINE_LOOP);
          qglVertex3f(vMin[0],vMin[1],vMin[2]);
